<script setup lang="ts">import{computed}from"vue";import{useRoute}from"vue-router";import FeatureStatusBadge from"../system/FeatureStatusBadge.vue";const props=defineProps<{open:boolean}>();const emit=defineEmits<{close:[]}>();const route=useRoute();const feature=computed(()=>route.meta.feature);</script><template><aside v-if="feature?.requiresContextRail" class="rail" :class="{open:props.open}"><header><div><p class="eyebrow">CONTEXT</p><h2>证据与上下文</h2></div><button aria-label="关闭上下文栏" @click="emit('close')">×</button></header><FeatureStatusBadge :status="feature.status"/><p>此区域将随页面承载来源、检索式或证据定位信息；当前不伪造任何论文或引文。</p></aside></template><style scoped>.rail{padding:1.2rem;border-left:1px solid var(--line);background:#fbfcfb}.rail header{display:flex;justify-content:space-between}.rail h2{margin:.2rem 0;font-size:1rem}.rail p{color:var(--muted);font-size:.86rem;line-height:1.6}.eyebrow{margin:0;color:var(--teal-600);font-size:.7rem;font-weight:800;letter-spacing:.12em}.rail button{border:0;background:transparent;font-size:1.2rem}@media(max-width:1100px){.rail{display:none}.rail.open{position:fixed;inset:0 0 0 auto;z-index:30;display:block;width:min(90vw,340px);box-shadow:var(--shadow)}}</style>
